-- pokemon に画像URL（PokeAPI sprites の公式アートワーク）を追加する。
-- 別フォルム・メガは PokeAPI 独自ID（10000番台）の画像を指す。対応表は form_code と PokeAPI のポケモン名から作成し、全URLの実在を確認済み（2026-10-17）。
-- 新規環境ではこの UPDATE は空振りし、../data/champions/data.sql の投入で image_url が入る。
ALTER TABLE pokemon ADD COLUMN image_url TEXT;

UPDATE pokemon SET image_url = 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/3.png' WHERE id = 1;
